        root = Node()
        for path in paths:
            root.add(path)
        hash_to_nodes = defaultdict(list)
        root.calc_hash(hash_to_nodes)
        for nodes in hash_to_nodes.values():
            if len(nodes) > 1:
                for node in nodes:
                    node.deleted = True
        res = []
        root.to_list(res)
