            if (i, k) in memoize:
                return memoize[(i, k)]

            _max = A[i]
            r = MAX
            for j in range(i-1, -2, -1):
                r = min(r, dp(j, k-1) + waste(j+1, i,  _max))
                _max = max(_max, A[j])

            memoize[(i, k)] = r
            return r

        sums = list(accumulate(A))
        n = len(A)
